/**
 * Config Flow 纯工具函数（lib 层，无 API/网络依赖）。
 *
 * <p>从 SPA {@code views/config-flow/service.js} 抽出 escapeHtml/transformFormData/isNumericField/isBooleanField，
 * 供 lib 内 flow-form 及外部复用。SPA service.js 原地保留（向后兼容，不反向依赖）。
 *
 * @module lib/config-flow/flow-service
 */

/**
 * HTML 转义（防 XSS）。用 DOM textContent→innerHTML 实现，与 SPA ConfigFlowService.escapeHtml 一致。
 */
export function escapeHtml(text) {
  if (text == null) return '';
  const div = document.createElement('div');
  div.textContent = String(text);
  return div.innerHTML;
}

/** 判断字段名是否数值类（按命名约定：calibration/baudrate/data_bits/stop_bits/port/timeout）。 */
export function isNumericField(fieldName) {
  if (!fieldName) return false;
  const numericPatterns = ['calibration', 'baudrate', 'data_bits', 'stop_bits', 'port', 'timeout'];
  return numericPatterns.some(p => fieldName.toLowerCase().includes(p));
}

/** 判断字段名是否布尔类（按命名约定：enabled/enable/active/disabled）。 */
export function isBooleanField(fieldName) {
  if (!fieldName) return false;
  const booleanPatterns = ['enabled', 'enable', 'active', 'disabled'];
  return booleanPatterns.some(p => fieldName.toLowerCase().includes(p));
}

/**
 * 转换 FormData 为正确类型（number/boolean/string）。
 * 逻辑与 SPA ConfigFlowService.transformFormData 一致（复制非引用，避免 lib 反向依赖 SPA）。
 */
export function transformFormData(formData, fields) {
  const data = {};
  const fieldTypes = {};
  fields.forEach(field => {
    const fieldKey = field.key || field.name;
    fieldTypes[fieldKey] = field.fieldType || field.type;
  });
  for (const [key, value] of formData.entries()) {
    if (value && value.trim() !== '') {
      const fieldType = fieldTypes[key] || 'text';
      if (fieldType === 'number' || fieldType === 'integer' || isNumericField(key)) {
        const numValue = Number(value);
        data[key] = isNaN(numValue) ? value : numValue;
      } else if (fieldType === 'boolean') {
        data[key] = true;
      } else {
        data[key] = value;
      }
    }
  }
  // 复选框未选中时补 false
  fields.forEach(field => {
    const fieldKey = field.key || field.name;
    if (field.type === 'boolean' || isBooleanField(fieldKey)) {
      if (!formData.has(fieldKey)) {
        data[fieldKey] = false;
      }
    }
  });
  return data;
}
