/**
 * ecat-config-flow lib 公共 API barrel。
 *
 * <p>外部（Ruoyi Vue 等）经此入口引入：
 * <pre>
 *   import { FlowForm, FieldRegistry, registerAllFieldRenderers, createConfigFlowApi, escapeHtml } from './ecat-config-flow.esm.js';
 * </pre>
 *
 * <p><b>不变性约束</b>：lib 永不反向依赖 views/、core/routes.js、SPA 事件——违反则不可外部复用。
 * 经 esbuild 打包成单文件 dist（lit 内联），或 SPA 原生 ESM 直接 import 此 barrel。
 *
 * @module lib/config-flow
 */

// 版本单一真相源（version.js）：bundle 与 SPA 源码路径同源；挂 window 供运行时无 import 场景查版本
import { CONFIG_FLOW_LIB_VERSION } from './version.js';
export { CONFIG_FLOW_LIB_VERSION };
if (typeof window !== 'undefined') {
  window.__ecatConfigFlowVersion = CONFIG_FLOW_LIB_VERSION;
}

// 触发 flow-form 模块加载（其顶部 registerAllFieldRenderers() 注册所有字段渲染器）
export { FlowForm } from './flow-form.js';

// 字段渲染子系统（Strategy + Registry）
export {
  FieldRegistry,
  registerAllFieldRenderers,
  FieldRenderer,
  TextFieldRenderer,
  NumericFieldRenderer,
  FloatFieldRenderer,
  ShortFieldRenderer,
  BooleanFieldRenderer,
  EnumFieldRenderer,
  ArrayFieldRenderer,
  SchemaFieldRenderer,
  YamlFieldRenderer,
  TableFieldRenderer
} from './fields/index.js';

// API 工厂 + 默认实例
export { createConfigFlowApi, configFlowApi } from './flow-api.js';

// 纯工具函数
export { escapeHtml, transformFormData, isNumericField, isBooleanField } from './flow-service.js';
