/**
 * BooleanFieldRenderer - Boolean Field Renderer
 * 布尔字段渲染器
 *
 * 支持 fieldType: 'boolean'
 * 渲染为 <input type="checkbox">
 */
import { html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

export class BooleanFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'boolean';
  }

  /**
   * 渲染布尔字段（复选框）
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldKey = this.getFieldKey(field);
    const isChecked = this.parseBoolean(value ?? field.defaultValue);

    return html`
      <div class="form-group">
        <div class="checkbox-wrapper">
          <input
            type="checkbox"
            id="${fieldKey}"
            name="${fieldKey}"
            ?checked=${isChecked}
          />
          <label for="${fieldKey}">
            ${field.displayName || fieldKey}
            ${field.required ? html`<span class="required">*</span>` : ''}
          </label>
        </div>
        ${field.description && !error ? html`<div class="hint">${this.escapeHtml(field.description)}</div>` : ''}
        ${this.renderError(error, html)}
      </div>
    `;
  }

  /**
   * 从表单数据获取字段值
   * 复选框只有选中时才有值
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {boolean} 布尔值
   */
  getValue(formData, field) {
    const fieldKey = this.getFieldKey(field);
    return formData.has(fieldKey);
  }

  /**
   * 获取默认值
   */
  getDefaultValue(field) {
    return this.parseBoolean(field.defaultValue);
  }

  /**
   * 解析布尔值
   * 支持多种格式：true/false, "true"/"false", 1/0, "yes"/"no"
   * @param {any} value - 原始值
   * @returns {boolean} 布尔值
   */
  parseBoolean(value) {
    if (value === null || value === undefined) {
      return false;
    }
    if (typeof value === 'boolean') {
      return value;
    }
    if (typeof value === 'string') {
      const lower = value.toLowerCase().trim();
      return lower === 'true' || lower === '1' || lower === 'yes' || lower === 'on';
    }
    return Boolean(value);
  }
}
