/**
 * TableFieldRenderer - 变长结构化行表渲染器(主行 + 详情渐进披露)
 *
 * fieldType: 'table'
 *
 * 渲染机制（浏览器实验证实 2026-07-03，2026-07-05 加主行/详情分组）：
 * - 自包含状态化 Lit 自定义元素 <table-field-renderer>，createRenderRoot 返回 this（light DOM）。
 *   关键：light-DOM <input> 落进 flow-form 的 <form>，new FormData(form) 能收到（实验：穿 host 边界的
 *   light-DOM 输入 ✅；自带 shadow-DOM 输入 ❌ 收不到，FormData 不穿透 shadow DOM）。
 * - 列分两组(后端列 DTO 的 displayGroup)：
 *     main  = 主行核心列(始终显,一屏概览)；
 *     detail= 详情列(行展开显,按 group 分组 + showWhen 渐进披露)。
 *   legacy 列(无 displayGroup)按 main 处理 → 退化成扁平全列表(向后兼容,无详情无展开)。
 * - 主行额外渲染一个"单位"派生列(只读 span,值= row.unit||row.attrClass||'—'),让主行一眼看到物理单位。
 * - 行展开:详情 <tr> 始终渲染,用 display:none 折叠(不条件渲染)。收起时字段仍在 <form> 内,
 *   getValue 扫 formData 照常收——收起≠丢数据。只有 showWhen 不匹配的字段才不渲染(渐进披露)。
 * - showWhen="field=v1|v2":同行 field 值在值集时显本列;如 conversion_type=LINEAR 才显系数/偏置。
 * - 单元格级联:列声明 dependsOn 时,按同行被依赖列的值前缀过滤本列 options(两级单位选择)。
 * - 增删开关(后端 TableConfigItem.allowAdd/allowDelete):===false 时隐藏"添加测点"/行"删除"按钮,
 *   用于行来源是外部动态清单的表(行由服务端生成,用户只编辑单元格);undefined 视为允许(兼容旧 schema)。
 *   两按钮都隐藏且无详情列时,操作列整个隐藏。
 *
 * 行不丢:handleStep 提交前自动把含表格行的 userInput 存进 step_inputs;重渲染时元素从 .value hydrate。
 */
import { LitElement, html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';
import { appConfirm } from '../../ui/app-dialog.js';

// 主行/详情表样式文本。table-field-renderer 虽是 light DOM,但位于 flow-form shadow 内——
// document 级 CSS 穿不透 shadow boundary,故各实例 connectedCallback 把 <style> 注入自身 getRootNode()
// (即所在 shadow root 或 document),确保样式作用到本元素。
const STYLE_TEXT = `
.ecat-config-table-masterdetail{width:100%;border-collapse:collapse;background:var(--bg,#fff);font-size:13px;table-layout:auto}
.ecat-config-table-masterdetail th,.ecat-config-table-masterdetail td{border:1px solid var(--border,#e0e0e0);padding:6px 8px;vertical-align:middle;text-align:left}
.ecat-config-table-masterdetail thead th{background:var(--secondary-light,#f1f5f9);font-weight:600;color:var(--text,#1f2937);white-space:nowrap}
.ecat-config-table-masterdetail .unit-col{width:90px}
.ecat-config-table-masterdetail .unit-cell{color:var(--text-muted,#6b7280);font-size:12px;white-space:nowrap;text-align:center;vertical-align:middle}
.ecat-config-table-masterdetail .op-col{width:80px;text-align:center}
.ecat-config-table-masterdetail .op-cell{text-align:center;white-space:nowrap;vertical-align:middle}
.ecat-config-table-masterdetail .op-cell .btn-icon{border:none;background:none;cursor:pointer;padding:5px;margin:0 2px;color:var(--text-muted,#6b7280);border-radius:var(--radius-sm,6px);display:inline-flex;align-items:center;justify-content:center;transition:all .15s;vertical-align:middle}
.ecat-config-table-masterdetail .op-cell .op-sep{display:inline-block;width:1px;height:18px;background:var(--border,#e0e0e0);margin:0 4px;vertical-align:middle}
.ecat-config-table-masterdetail .op-cell .btn-icon:hover{background:var(--secondary-light,#f1f5f9);color:var(--text,#1f2937)}
.ecat-config-table-masterdetail .op-cell .btn-icon.btn-remove:hover{color:var(--danger,#ef4444);background:#fef2f2}
.ecat-config-table-masterdetail .op-cell .btn-icon svg{width:16px;height:16px;display:block}
/* 单元格内 field-renderer 把 label 包在 .form-group 里(嵌套),与表头/详情外层 label 重复,隐藏之。
   详情区 boolean 字段(可写)的 label 在 .checkbox-wrapper 内(孙级,非 .form-group 直接子),
   故须单独列 .checkbox-wrapper > label,否则"可写*"会显示两份(detail-field 外层 label + checkbox 旁 label)。 */
.ecat-config-table-masterdetail td .form-group > label,
.detail-field .form-group > label,
.detail-field .checkbox-wrapper > label{display:none}
/* 单元格内 field-renderer 把输入包在 .form-group 里,而全局 .form-group 有 margin-bottom:20px(flow-form.js)
   会撑高每个 cell、行底凭空多一截空白(看着像"多一行")。表格行要紧凑,这里清零 cell 内 form-group 的 margin。 */
.ecat-config-table-masterdetail td .form-group{margin:0}
.ecat-config-table-masterdetail td input,.ecat-config-table-masterdetail td select{padding:4px 6px;border:1px solid var(--border,#e0e0e0);border-radius:var(--radius-sm,6px);font-size:13px;width:100%;box-sizing:border-box;background:var(--bg,#fff)}
.ecat-config-table-masterdetail td input:focus,.ecat-config-table-masterdetail td select:focus{outline:none;border-color:var(--primary,#4f6ef7)}
.ecat-config-table-masterdetail td input[type="checkbox"]{width:auto}
.btn-add-row{margin-top:10px;padding:7px 14px;cursor:pointer;border:1px solid var(--primary,#4f6ef7);background:var(--primary-light,#eef2ff);color:var(--primary,#4f6ef7);border-radius:var(--radius-sm,6px);font-size:13px;font-weight:500;transition:all .2s;display:inline-flex;align-items:center;gap:5px}
.btn-add-row:hover{background:var(--primary,#4f6ef7);color:#fff}
.btn-add-row svg{width:16px;height:16px;display:block}
.detail-row>td{background:var(--bg-gray,#f8f9fa);padding:0;border-top:none;border-left:1px solid var(--border,#e0e0e0);border-right:1px solid var(--border,#e0e0e0)}
.detail-card{padding:12px 16px;border-left:3px solid var(--primary,#4f6ef7);background:var(--bg,#fff);margin:2px 0 8px;border-radius:0 var(--radius-sm,6px) var(--radius-sm,6px) 0}
.detail-group{margin-bottom:14px}
.detail-group:last-child{margin-bottom:0}
.detail-group-title{font-size:12px;font-weight:600;color:var(--primary,#4f6ef7);margin-bottom:8px}
.detail-fields{display:flex;flex-wrap:wrap;gap:10px 20px}
.detail-field{display:flex;flex-direction:column;min-width:150px;flex:0 0 auto}
.detail-field > label{font-size:12px;color:var(--text-muted,#6b7280);margin-bottom:4px;white-space:nowrap;font-weight:500}
.detail-field input,.detail-field select,.detail-field textarea{padding:5px 8px;border:1px solid var(--border,#e0e0e0);border-radius:var(--radius-sm,6px);font-size:13px;min-width:120px;background:var(--bg,#fff)}
.detail-field input:focus,.detail-field select:focus{outline:none;border-color:var(--primary,#4f6ef7)}
.detail-empty{color:var(--text-muted,#6b7280);font-size:12px;padding:6px 0}
`;

// Heroicons outline 图标(同 entries.js/flow-complete 风格:fill=none / stroke=currentColor / stroke-width=2 / round caps)
const ICO = {
  chevronRight: html`<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>`,
  chevronDown: html`<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>`,
  trash: html`<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>`,
  plus: html`<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>`,
};

let _FieldRegistry = null;
export function setFieldRegistry(registry) { _FieldRegistry = registry; }

/** 单元格渲染：委托注册表，产物是 <input>/<select>，落进本元素 light DOM（= flow-form <form> 内）。 */
function renderCell(col, fieldKey, rowIdx, cellValue, cellError) {
  const r = _FieldRegistry ? _FieldRegistry.getRenderer(col.fieldType) : null;
  if (!r) {
    return html`<span class="field-error">无渲染器:${col.fieldType}</span>`;
  }
  const prefixed = Object.assign({}, col, { key: `${fieldKey}.${rowIdx}.${col.key}` });
  return r.render(prefixed, cellValue, cellError);
}

/**
 * 状态化自定义元素。light DOM（createRenderRoot 返回 this）。
 */
export class TableFieldRendererElement extends LitElement {
  static properties = {
    field: { type: Object },
    value: { type: Object },
    error: { type: Object },
    _rows: { state: true },
    _expanded: { state: true },   // {rowIdx: bool} 详情展开状态
  };

  createRenderRoot() { return this; }   // light DOM：FormData 收不到 shadow-DOM 输入，必须落进 flow-form 的 <form>

  constructor() { super(); this._expanded = {}; }

  connectedCallback() {
    super.connectedCallback();
    // 本元素 light DOM 但位于 flow-form shadow 内——document 级 CSS 穿不透 shadow boundary,
    // 故把 <style> 注入自身 getRootNode()(shadow root 或 document),样式才作用到本元素。每 root 一次(id 去重)。
    const root = this.getRootNode();
    if (root && root.getElementById && !root.getElementById('ecat-table-field-styles')) {
      const s = document.createElement('style');
      s.id = 'ecat-table-field-styles';
      s.textContent = STYLE_TEXT;
      (root.head || root).appendChild(s);
    }
  }

  willUpdate(changed) {
    // 从服务端回显的 value hydrate 行；field.key 变化时重置（防 flow-form positional 复用串状态）
    if (changed.has('value') || changed.has('field')) {
      const v = Array.isArray(this.value)
        ? this.value
        : (Array.isArray(this.field && this.field.defaultValue) ? this.field.defaultValue : []);
      // 仅当有真实回显数据(非空数组)时才 hydrate _rows;空/undefined 时**保留** _rows:
      // 嵌套子表(segments/enum_map)场景下,外层 table-field 不持有子表状态(子表自管 _rows),
      // 外层每次重渲染都把 .value=${row.segments}=undefined 传给子表实例 → 触发本 willUpdate;
      // 若空也重置会冲掉用户在子表里手动建的行(填一格外层重渲染即消失)。空值仅在首次初始化 [] 用。
      if (v.length > 0) {
        this._rows = v.map(r => Object.assign({}, r));
      } else if (this._rows === undefined) {
        this._rows = [];
      }
    }
  }

  _fieldKey() { return (this.field && (this.field.key || this.field.name)) || ''; }
  _columns() { return (this.field && this.field.columns) || []; }
  /** 允许用户添加行（后端 allowAdd===false 时禁止；undefined 视为允许，兼容旧 schema）。 */
  _allowAdd() { return !(this.field && this.field.allowAdd === false); }
  /** 允许用户删除行（后端 allowDelete===false 时禁止；undefined 视为允许，兼容旧 schema）。 */
  _allowDelete() { return !(this.field && this.field.allowDelete === false); }
  /** 主行核心列(无 displayGroup 视为 main,向后兼容扁平表)。 */
  _mainCols() { return this._columns().filter(c => !c.displayGroup || c.displayGroup === 'main'); }
  /** 详情列(displayGroup=detail)。空 = legacy 扁平表,无详情无展开。 */
  _detailCols() { return this._columns().filter(c => c.displayGroup === 'detail'); }

  _addRow() {
    const idx = this._rows.length;
    // 预填各列 defaultValue 进新行,使行状态 = 显示默认值。否则新行是空 {},combobox 虽按 defaultValue
    // 视觉选中(如"线性"),但 row.conversion_type 仍 undefined → _matchShowWhen 读 row.conversion_type
    // 失败 → factor/offset/segments 等 showWhen 字段不渲染(用户加 LINEAR 行却看不到偏置框,以为字段缺失)。
    // 预填后 row.conversion_type=LINEAR → showWhen 通过 → 转换参数组正常显。无默认值的列(地址/系数/偏置等)
    // 仍 undefined,不预填。FormData 收集不受影响:渲染的输入照常收,未渲染的(showWhen 隐藏)本就不收。
    const defaults = {};
    for (const c of this._columns()) {
      const dv = c.defaultValue;
      if (dv !== undefined && dv !== null && dv !== '') {
        defaults[c.key] = dv;
      }
    }
    this._rows = [...this._rows, defaults];
    this._expanded = Object.assign({}, this._expanded, { [idx]: true });   // 新行展开引导填
  }
  async _removeRow(idx) {
    if (!(await appConfirm('确定删除该测点?'))) return;   // 防误删:删除前确认
    this._rows = this._rows.filter((_, i) => i !== idx);
    // 行删除后重建 _expanded(后续行 index 前移)
    const ne = {};
    Object.keys(this._expanded).forEach(k => { const ki = +k; if (ki < idx) ne[ki] = this._expanded[k]; else if (ki > idx) ne[ki - 1] = this._expanded[k]; });
    this._expanded = ne;
  }
  _toggle(idx) { this._expanded = Object.assign({}, this._expanded, { [idx]: !this._expanded[idx] }); }

  /** 单元格 change → 写回本行 _rows 并触发重渲染（Lit 响应；级联列据此刷新）。 */
  _onCellChange(idx, colKey, ev) {
    // 嵌套 table 列(segments/enum_map 子表)自管理状态:子 table-field 内部维护自己的行,
    // 提交时由其 getValue 收集。它的深层单元格 change 会冒泡到本 <td>,此时 ev.target 是子表
    // 内的 input(如 rawMin),.value 是标量;若照常 _rows[idx][colKey]=标量,会冲掉子表整列状态,
    // 子表按被破坏的 value 重渲染 → 正在编辑的行丢失(手动建折线段/枚举表时填一格就消失)。
    // 故嵌套 table 列跳过(本回调只服务 U4 级联:unit_category→unit 等,非 table 列)。
    const col = this._columns().find(c => c.key === colKey);
    if (col && col.fieldType === 'table') return;
    // multi_select 单元格是 checkbox 组(同名多 input),单次 change 只代表一个 box 的状态;
    // 若照常取 ev.target.value(标量)写回,重渲染按 row[colKey]=标量 hydrate 会只剩最后勾的 box。
    // 故聚合本单元格(名字带 fieldKey.rowIdx 前缀,全表唯一)所有 checked 的值写成数组。
    if (col && col.fieldType === 'multi_select') {
      const cellName = `${this._fieldKey()}.${idx}.${colKey}`;
      const checked = Array.from(this.querySelectorAll(`input[name="${cellName}"]:checked`)).map(i => i.value);
      this._rows = this._rows.map((r, i) => (i === idx ? Object.assign({}, r, { [colKey]: checked }) : r));
      return;
    }
    const el = ev && ev.target;
    // checkbox 的 ev.target.value 恒为 "on"(input 无 value 属性时的默认),若照常用 .value 会把 row.writable
    // 写成 "on",而 writeAddress 的 showWhen 是 "writable=true" → _matchShowWhen 比 String("on")!=="true" 失败
    // → 用户勾"可写"后"写地址"框不显(create 表单交互专属缺陷;reconfigure 预填走 toRow 的布尔值不受影响)。
    // 故 checkbox 用 .checked(布尔),row.writable=true → String(true)==="true" → showWhen 通过 → writeAddress 显。
    const val = el ? (el.type === 'checkbox' ? el.checked : el.value) : undefined;
    if (val === undefined) return;
    this._rows = this._rows.map((r, i) => (i === idx ? Object.assign({}, r, { [colKey]: val }) : r));
  }

  /** U4 级联：列声明 dependsOn 时，按同行被依赖列的值前缀过滤本列 options。 */
  _filteredCol(row, col) {
    if (!col || !col.dependsOn) return col;
    const depVal = row && row[col.dependsOn];
    if (!depVal) return Object.assign({}, col, { options: [] });   // 未选类别 → 本列空
    const prefix = depVal + '.';
    const opts = Array.isArray(col.options)
      ? col.options.filter(o => String(o.value != null ? o.value : o).startsWith(prefix))
      : [];
    return Object.assign({}, col, { options: opts });
  }

  /** showWhen="field=v1|v2":同行 field 命中值集才显本列;null/无= 无条件显。 */
  _matchShowWhen(row, showWhen) {
    if (!showWhen) return true;
    const eq = showWhen.indexOf('=');
    if (eq < 0) return true;
    const field = showWhen.substring(0, eq);
    const vals = showWhen.substring(eq + 1).split('|');
    return vals.includes(String(row[field]));
  }

  /** 详情可见列(showWhen 过滤后)按 group 聚合 → [[group,[cols]]](保持 group 首次出现顺序)。 */
  _groupedDetail(row) {
    const map = new Map();
    for (const c of this._detailCols()) {
      if (!this._matchShowWhen(row, c.showWhen)) continue;
      const g = c.group || '其他';
      if (!map.has(g)) map.set(g, []);
      map.get(g).push(c);
    }
    return [...map.entries()];
  }

  /** 主行"单位"派生列(只读):有单位→显单位 label(从 unit 列 options 映射 value→label,如 °C);没选单位→显"无"。
   * 单位列只表达单位,不 fallback 属性类别——属性类别已有专门列,没选单位时若显属性类型会让用户误以为那就是单位。 */
  _unitDisplay(row) {
    if (row.unit) {
      const unitCol = this._detailCols().find(c => c.key === 'unit');
      const opts = unitCol && Array.isArray(unitCol.options) ? unitCol.options : null;
      if (opts) {
        const opt = opts.find(o => (o.value != null ? o.value : o) === row.unit);
        if (opt && opt.label) return opt.label;
      }
      return row.unit;   // 无映射(legacy/未匹配)→ 显原始 value
    }
    return '无';
  }

  _cellError(idx, colKey) {
    const isRowError = this.error && typeof this.error === 'object' && !Array.isArray(this.error);
    return isRowError && this.error[idx] ? (this.error[idx][colKey] || null) : null;
  }

  render() {
    const fieldKey = this._fieldKey();
    const mainCols = this._mainCols();
    const hasDetail = this._detailCols().length > 0;
    // 操作列内容 = 行删除按钮 + 详情展开按钮(有详情时)。allowDelete=false 且无详情列时操作列
    // 整个隐藏(无任何可渲染的操作);有详情时展开按钮仍在,操作列保留。
    const hasOpCol = this._allowDelete() || hasDetail;
    // main 列 + 单位列(有详情时) + 操作列(未隐藏时)
    const colspan = mainCols.length + (hasDetail ? 1 : 0) + (hasOpCol ? 1 : 0);
    return html`
      <div class="form-group table-group" data-field-key="${fieldKey}">
        <label>${(this.field && this.field.displayName) || fieldKey}${this.field && this.field.required ? html`<span class="required">*</span>` : ''}</label>
        <table class="ecat-config-table ecat-config-table-masterdetail">
          <thead>
            <tr>
              ${mainCols.map(c => html`<th>${c.displayName || c.key}${c.required ? html`<span class="required">*</span>` : ''}</th>`)}
              ${hasDetail ? html`<th class="unit-col">单位</th>` : ''}
              ${hasOpCol ? html`<th class="op-col">操作</th>` : ''}
            </tr>
          </thead>
          <tbody>
            ${this._rows.map((row, idx) => html`
              <tr data-row="${idx}">
                ${mainCols.map(col => html`<td @change=${e => this._onCellChange(idx, col.key, e)}>${renderCell(this._filteredCol(row, col), fieldKey, idx, row[col.key], this._cellError(idx, col.key))}</td>`)}
                ${hasDetail ? html`<td class="unit-cell">${this._unitDisplay(row)}</td>` : ''}
                ${hasOpCol ? html`
                <td class="op-cell">
                  ${hasDetail ? html`<button type="button" class="btn-icon btn-expand" @click=${() => this._toggle(idx)} title="${this._expanded[idx] ? '收起详情' : '展开详情'}">${this._expanded[idx] ? ICO.chevronDown : ICO.chevronRight}</button><span class="op-sep" role="separator"></span>` : ''}
                  ${this._allowDelete() ? html`<button type="button" class="btn-icon btn-remove" @click=${() => this._removeRow(idx)} title="删除测点">${ICO.trash}</button>` : ''}
                </td>
                ` : ''}
              </tr>
              ${hasDetail ? html`
                <tr class="detail-row" style="${this._expanded[idx] ? '' : 'display:none'}"><td colspan="${colspan}">
                  <div class="detail-card">
                    ${this._groupedDetail(row).map(([group, cols]) => html`
                      <div class="detail-group">
                        <div class="detail-group-title">${group}</div>
                        <div class="detail-fields">
                          ${cols.map(col => html`
                            <div class="detail-field" @change=${e => this._onCellChange(idx, col.key, e)}>
                              <label>${col.displayName || col.key}${col.required ? html`<span class="required">*</span>` : ''}</label>
                              ${renderCell(this._filteredCol(row, col), fieldKey, idx, row[col.key], this._cellError(idx, col.key))}
                            </div>
                          `)}
                        </div>
                      </div>
                    `)}
                    ${this._groupedDetail(row).length === 0 ? html`<div class="detail-empty">无附加配置项</div>` : ''}
                  </div>
                </td></tr>
              ` : ''}
            `)}
          </tbody>
        </table>
        ${this._allowAdd() ? html`<button type="button" class="btn-add-row" @click=${() => this._addRow()}>${ICO.plus} 添加测点</button>` : ''}
      </div>
    `;
  }
}
customElements.define('table-field-renderer', TableFieldRendererElement);

/**
 * FieldRenderer 包装：render 产出 <table-field-renderer>；getValue 按 fieldKey.rowIdx.colKey 解析行。
 */
export class TableFieldRenderer extends FieldRenderer {
  static get fieldType() { return 'table'; }

  render(field, value, error) {
    return html`<table-field-renderer .field=${field} .value=${value} .error=${error}></table-field-renderer>`;
  }

  /** 提交时：扫 formData 里 fieldKey.<rowIdx>.<colKey>，按 rowIdx 聚成行数组。 */
  getValue(formData, field) {
    const fieldKey = field.key || field.name;
    const columns = field.columns || [];
    const prefix = fieldKey + '.';
    const idxSet = new Set();
    const keys = formData.keys ? Array.from(formData.keys()) : Object.keys(formData);
    for (const k of keys) {
      if (typeof k === 'string' && k.startsWith(prefix)) {
        const rest = k.substring(prefix.length);
        const dot = rest.indexOf('.');
        if (dot > 0) idxSet.add(parseInt(rest.substring(0, dot), 10));
      }
    }
    const rows = [];
    for (const idx of [...idxSet].sort((a, b) => a - b)) {
      const row = {};
      for (const col of columns) {
        const r = _FieldRegistry ? _FieldRegistry.getRenderer(col.fieldType) : null;
        const prefixed = Object.assign({}, col, { key: `${prefix}${idx}.${col.key}` });
        const v = r ? r.getValue(formData, prefixed) : undefined;
        if (v !== undefined && v !== null && v !== '') row[col.key] = v;
      }
      rows.push(row);
    }
    return rows;
  }

  getDefaultValue(field) {
    return Array.isArray(field.defaultValue) ? field.defaultValue : [];
  }
}
