/**
 * FieldRegistry - Field Renderer Registry
 * 字段渲染器注册表
 *
 * 使用 Registry Pattern 管理字段渲染器
 * 通过 fieldType 自动匹配合适的渲染器
 */
class FieldRegistryImpl {
  constructor() {
    this.renderers = new Map();
    this.defaultFieldType = 'text';
  }

  /**
   * 注册渲染器
   * @param {class} RendererClass - 渲染器类（必须继承 FieldRenderer）
   * @throws {Error} 如果渲染器未定义 fieldType
   */
  register(RendererClass) {
    const type = RendererClass.fieldType;
    if (!type) {
      throw new Error(`Renderer must define static fieldType. Got: ${RendererClass.name}`);
    }
    const instance = new RendererClass();
    this.renderers.set(type, instance);
    console.debug(`[FieldRegistry] Registered renderer for fieldType: ${type}`);
  }

  /**
   * 获取指定类型的渲染器
   * @param {string} fieldType - 字段类型
   * @returns {FieldRenderer|null} 渲染器实例
   */
  getRenderer(fieldType) {
    return this.renderers.get(fieldType) || null;
  }

  /**
   * 检查是否已注册指定类型的渲染器
   * @param {string} fieldType - 字段类型
   * @returns {boolean}
   */
  hasRenderer(fieldType) {
    return this.renderers.has(fieldType);
  }

  /**
   * 获取所有已注册的字段类型
   * @returns {string[]}
   */
  getRegisteredTypes() {
    return Array.from(this.renderers.keys());
  }

  /**
   * 渲染字段
   * 自动根据 field.fieldType 匹配渲染器
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值
   * @param {string} error - 错误信息
   * @returns {import('lit').TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldType = field.fieldType || field.type || this.defaultFieldType;
    const renderer = this.getRenderer(fieldType);

    if (!renderer) {
      console.warn(
        `[FieldRegistry] Unknown fieldType: "${fieldType}", falling back to "${this.defaultFieldType}". ` +
        `Field: ${field.key || field.name}`
      );
      return this.getRenderer(this.defaultFieldType).render(field, value, error);
    }

    return renderer.render(field, value, error);
  }

  /**
   * 从表单数据获取字段值
   * 自动根据 field.fieldType 匹配渲染器
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {any} 字段值
   */
  getValue(formData, field) {
    const fieldType = field.fieldType || field.type || this.defaultFieldType;
    const renderer = this.getRenderer(fieldType);

    if (!renderer) {
      // Fallback: 直接获取表单值
      const fieldKey = field.key || field.name;
      return formData.get(fieldKey);
    }

    return renderer.getValue(formData, field);
  }

  /**
   * 获取字段的默认值
   * @param {Object} field - 字段 Schema
   * @returns {any} 默认值
   */
  getDefaultValue(field) {
    const fieldType = field.fieldType || field.type || this.defaultFieldType;
    const renderer = this.getRenderer(fieldType);

    if (!renderer) {
      return field.defaultValue;
    }

    return renderer.getDefaultValue(field);
  }
}

// 单例导出
export const FieldRegistry = new FieldRegistryImpl();
