/**
 * Flow Form Component
 * 动态配置表单组件
 *
 * 使用 FieldRegistry (Strategy + Registry Pattern) 渲染字段
 * 无 if/switch 判断字段类型，通过 fieldType 自动匹配渲染器
 */
import { LitElement, html, css } from '../../lib/lit/index.js';
import { escapeHtml } from './flow-service.js';
import { registerAllFieldRenderers, FieldRegistry } from './fields/index.js';

// 初始化：注册所有字段渲染器
registerAllFieldRenderers();

export class FlowForm extends LitElement {
  static styles = css`
    :host { display: block; }
    .form-container { padding: 20px; }
    .step-title {
      font-size: 20px;
      font-weight: 600;
      color: #1f2937;
      margin-bottom: 8px;
    }
    .step-description {
      color: #6b7280;
      font-size: 14px;
      margin-bottom: 20px;
    }
    .form-group { margin-bottom: 20px; }
    .form-group label {
      display: block;
      font-weight: 500;
      color: #374151;
      margin-bottom: 6px;
    }
    .form-group label .required { color: #ef4444; margin-left: 2px; }
    .form-group input,
    .form-group select {
      width: 100%;
      padding: 10px 12px;
      border: 1px solid #d1d5db;
      border-radius: 6px;
      font-size: 14px;
      box-sizing: border-box;
    }
    .form-group input:focus,
    .form-group select:focus {
      outline: none;
      border-color: #667eea;
      box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.2);
    }
    .form-group input[readonly] {
      background: #f3f4f6;
      color: #6b7280;
      cursor: default;
    }
    .form-group input[readonly]:focus {
      border-color: #d1d5db;
      box-shadow: none;
    }
    .form-group .error {
      font-size: 12px;
      color: #ef4444;
      margin-top: 4px;
    }
    .form-group .hint {
      font-size: 12px;
      color: #6b7280;
      margin-top: 4px;
    }
    .checkbox-wrapper {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .checkbox-wrapper input[type="checkbox"] {
      width: 18px;
      height: 18px;
      cursor: pointer;
    }
    .checkbox-wrapper label {
      font-weight: normal;
      margin: 0;
      cursor: pointer;
    }
    .button-group {
      display: flex;
      gap: 12px;
      margin-top: 24px;
      padding-top: 20px;
      border-top: 1px solid #e5e7eb;
    }
    .btn {
      padding: 10px 24px;
      border: none;
      border-radius: 6px;
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.2s;
    }
    .btn:disabled { opacity: 0.5; cursor: not-allowed; }
    .btn-primary {
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
    }
    .btn-secondary {
      background: #6b7280;
      color: white;
    }
    .readonly-field {
      padding: 10px 12px;
      background: #f3f4f6;
      border-radius: 6px;
      color: #6b7280;
      font-size: 14px;
    }
    /* Array Field Styles */
    .array-container {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .array-item {
      display: flex;
      gap: 8px;
      align-items: center;
    }
    .array-item input {
      flex: 1;
    }
    .add-btn,
    .remove-btn {
      padding: 6px 12px;
      border: none;
      border-radius: 4px;
      font-size: 14px;
      cursor: pointer;
      transition: all 0.2s;
    }
    .add-btn {
      background: #e0e7ff;
      color: #4f46e5;
    }
    .add-btn:hover {
      background: #c7d2fe;
    }
    .remove-btn {
      background: #fee2e2;
      color: #dc2626;
      width: 32px;
      height: 36px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      line-height: 1;
    }
    .remove-btn:hover {
      background: #fecaca;
    }
    /* Array Checkbox Group */
    .checkbox-group {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    /* Object Field Styles */
    .object-group fieldset,
    .nested-fieldset {
      border: 1px solid #d1d5db;
      border-radius: 6px;
      padding: 16px;
      margin: 0;
    }
    .object-legend,
    .nested-fieldset legend {
      font-size: 13px;
      font-weight: 500;
      color: #6b7280;
      padding: 0 8px;
      margin: 0;
    }
    .nested-fieldset legend .required {
      color: #ef4444;
      margin-left: 2px;
    }
    .nested-fields .form-group {
      margin-bottom: 12px;
    }
    .nested-fields .form-group:last-child {
      margin-bottom: 0;
    }
    /* Schema Nested Group */
    .nested-group {
      margin-bottom: 20px;
    }
    .nested-group:last-child {
      margin-bottom: 0;
    }
  `;

  static properties = {
    flowId: { type: String },
    stepId: { type: String },
    schema: { type: Object },
    data: { type: Object },
    errors: { type: Object },
    navigation: { type: Object },
    loading: { type: Boolean }
  };

  constructor() {
    super();
    this.flowId = '';
    this.stepId = '';
    this.schema = {};
    this.data = {};
    this.errors = {};
    this.navigation = {};
    this.loading = false;
  }

  get isFirstStep() {
    return this.navigation?.isFirstStep ?? true;
  }

  get isLastStep() {
    return this.navigation?.isLastStep ?? false;
  }

  handleSubmit(e) {
    e.preventDefault();
    const form = this.shadowRoot.querySelector('form');
    if (!form) return;

    const formData = new FormData(form);
    const fields = this.schema?.fields || [];

    // 使用 FieldRegistry 获取每个字段的值
    const userInput = {};
    for (const field of fields) {
      const fieldKey = field.key || field.name;
      userInput[fieldKey] = FieldRegistry.getValue(formData, field);
    }

    this.dispatchEvent(new CustomEvent('flow-submit', {
      detail: { flowId: this.flowId, stepId: this.stepId, userInput },
      bubbles: true,
      composed: true
    }));
  }

  handlePrevious(e) {
    e.preventDefault();
    // 收集当前表单数据，支持步骤漫游
    const form = this.shadowRoot.querySelector('form');
    const formData = form ? new FormData(form) : new FormData();
    const fields = this.schema?.fields || [];
    const userInput = {};
    for (const field of fields) {
      const fieldKey = field.key || field.name;
      userInput[fieldKey] = FieldRegistry.getValue(formData, field);
    }
    this.dispatchEvent(new CustomEvent('flow-previous', {
      detail: { flowId: this.flowId, stepId: this.stepId, userInput },
      bubbles: true,
      composed: true
    }));
  }

  handleInput(e) {
    // 当用户输入时，清除该字段的错误信息
    const fieldKey = e.target.name || e.target.id;
    if (fieldKey && this.errors && this.errors[fieldKey]) {
      // 创建新的 errors 对象，移除当前字段的错误
      this.errors = { ...this.errors };
      delete this.errors[fieldKey];
      this.requestUpdate();
    }
  }

  renderField(field) {
    // API 返回 field.key，不是 field.name
    const fieldKey = field.key || field.name;

    // 从 step_inputs[stepId] 读取当前步骤已填写的数据
    // 支持步骤数据漫游：返回上一步时显示之前填写的内容
    const stepInputs = this.data?.step_inputs || {};
    const currentStepData = stepInputs[this.stepId] || {};
    const value = currentStepData[fieldKey] ?? field.defaultValue ?? '';

    const error = this.errors[fieldKey];

    // 使用 FieldRegistry 自动匹配渲染器
    // 通过 field.fieldType 或 field.type 确定渲染器
    return FieldRegistry.render(field, value, error);
  }

  render() {
    const fields = this.schema?.fields || [];
    const title = this.schema?.title || '配置';
    const description = this.schema?.description || '';

    return html`
      <div class="form-container">
        <h3 class="step-title">${escapeHtml(title)}</h3>
        ${description ? html`<p class="step-description">${escapeHtml(description)}</p>` : ''}

        <form @submit=${this.handleSubmit} @input=${this.handleInput}>
          ${fields.map(field => this.renderField(field))}

          <div class="button-group">
            ${!this.isFirstStep ? html`
              <button
                type="button"
                class="btn btn-secondary"
                @click=${this.handlePrevious}
                ?disabled=${this.loading}
              >
                ← 上一步
              </button>
            ` : ''}
            <button
              type="submit"
              class="btn btn-primary"
              ?disabled=${this.loading}
            >
              ${this.loading ? '处理中...' : '下一步 →'}
            </button>
          </div>
        </form>
      </div>
    `;
  }
}

customElements.define('flow-form', FlowForm);
export default FlowForm;
