/**
 * Field Renderers Module
 * 字段渲染器模块
 *
 * 统一导出和注册所有字段渲染器
 * 使用 Strategy + Registry Pattern
 */
import { FieldRegistry } from './field-registry.js';

// 导入渲染器类
import { TextFieldRenderer } from './text-field.js';
import { DateTimeFieldRenderer } from './datetime-field.js';
import { NumericFieldRenderer } from './numeric-field.js';
import { FloatFieldRenderer } from './float-field.js';
import { ShortFieldRenderer } from './short-field.js';
import { BooleanFieldRenderer } from './boolean-field.js';
import { EnumFieldRenderer } from './enum-field.js';
import { ArrayFieldRenderer } from './array-field.js';
import { MultiSelectFieldRenderer } from './multi-select-field.js';
import { SchemaFieldRenderer, setFieldRegistry } from './schema-field.js';
import { YamlFieldRenderer } from './yaml-field.js';
import { TableFieldRenderer, setFieldRegistry as setFieldRegistryForTable } from './table-field.js';

/**
 * 注册所有字段渲染器
 */
export function registerAllFieldRenderers() {
  FieldRegistry.register(TextFieldRenderer);
  FieldRegistry.register(DateTimeFieldRenderer);
  FieldRegistry.register(NumericFieldRenderer);
  FieldRegistry.register(FloatFieldRenderer);
  FieldRegistry.register(ShortFieldRenderer);
  FieldRegistry.register(BooleanFieldRenderer);
  FieldRegistry.register(EnumFieldRenderer);
  FieldRegistry.register(ArrayFieldRenderer);
  FieldRegistry.register(MultiSelectFieldRenderer);
  FieldRegistry.register(SchemaFieldRenderer);
  FieldRegistry.register(YamlFieldRenderer);
  FieldRegistry.register(TableFieldRenderer);

  // 为 EnumFieldRenderer 额外注册 'select' 类型
  FieldRegistry.renderers.set('select', new EnumFieldRenderer());

  // 为 EnumFieldRenderer 额外注册 'dynamic_enum' 类型
  // dynamic_enum 与 enum 渲染逻辑相同，都是下拉选择框
  FieldRegistry.renderers.set('dynamic_enum', new EnumFieldRenderer());

  // 设置 FieldRegistry 到 SchemaFieldRenderer，支持递归渲染
  setFieldRegistry(FieldRegistry);
  setFieldRegistryForTable(FieldRegistry);

  console.info('[FieldRenderers] All field renderers registered:', FieldRegistry.getRegisteredTypes());
}

// 导出注册表和渲染器类
export { FieldRegistry };
export { FieldRenderer, normalizeFieldOptions } from './field-renderer.js';
export { TextFieldRenderer } from './text-field.js';
export { DateTimeFieldRenderer, toControlValue, fromControlValue } from './datetime-field.js';
export { NumericFieldRenderer } from './numeric-field.js';
export { FloatFieldRenderer } from './float-field.js';
export { ShortFieldRenderer } from './short-field.js';
export { BooleanFieldRenderer } from './boolean-field.js';
export { EnumFieldRenderer } from './enum-field.js';
export { ArrayFieldRenderer } from './array-field.js';
export { MultiSelectFieldRenderer } from './multi-select-field.js';
export { SchemaFieldRenderer } from './schema-field.js';
export { YamlFieldRenderer } from './yaml-field.js';
export { TableFieldRenderer } from './table-field.js';
