/**
 * MultiSelectFieldRenderer - 受限多选字段渲染器（下拉多选形态）
 *
 * 支持 fieldType: 'multi_select'
 * 选项由后端 MultiSelectConfigItem 预定义，用户只能勾/不勾，不能自由输入。
 *
 * 交互形态（2026-08 用户定稿）：收起态 = 单行只读触发框（选中项 label 用「/」连接 + ▾ 三角，
 * 超长 ellipsis + hover title 全量，空集显占位「未选择」）；点击展开 = 绝对浮层内 checkbox 列表
 * （max-height 240px 出滚动条）+ 底部 [取消][保存]。勾选仅改浮层内部状态不即时生效：
 * 保存 = 提交勾选 + 触发 change（走 table-field _onCellChange 聚合路径）；取消 = 恢复打开时快照，
 * 不触发 change。点击浮层外部 / ESC / 滚动视口 = 取消。全局同时只开一个浮层（模块级单例）。
 *
 * FormData 收集（与 array-field 同一模式，不可破坏）：真 checkbox 共享 name 落在本元素
 * light DOM 内 = flow-form 的 <form> 里，浏览器把每个 checked 提交一条记录，getValue 用
 * formData.getAll(fieldKey) 聚合成数组。浮层只是视觉层（position:fixed），DOM 上仍是 <form>
 * 后代——保存/取消只切换勾选状态，不增删 input，提交收集路径零改动。
 *
 * 浮层定位选型：position:fixed + getBoundingClientRect 视口定位（不用单元格内 absolute）。
 * 宿主页面（SPA views/config-flow/index.js 的 :host{overflow:hidden} + .content{overflow-y:auto}，
 * 以及 ruoyi 侧弹层）都是滚动/裁剪容器，absolute 会被裁剪且随内容滚动错位；fixed 的包含块
 * 是视口，不被祖先 overflow 裁剪。代价：触发框随其所在容器滚动而移动、浮层不动——
 * 处理为「触发框视口位置因滚动而变化」才按取消收起（浮层内部滚动除外）；无关容器
 * （如后台实时日志面板自动滚动）不移动触发框，不得打断勾选草稿——2026-09-11 修复：
 * 全局捕获式 scroll 一律取消会误杀（日志面板 scrollTop 赋值即触发 scroll 事件，
 * 后台滚一下正在勾的多选就没了）。z-index:3000 盖过表格行与宿主 loading 遮罩(1000)。
 *
 * readOnly 处理：checkbox 不支持 readonly（浏览器忽略），disabled 的 checkbox 会被 FormData
 * 排除（丢值）。故 readOnly 时渲染 disabled checkbox + 为每个已选值补 <input type="hidden">
 * （hidden 不受 disabled 影响），值照常进 FormData；触发框呈灰态且不可展开。
 */
import { LitElement, html } from '../../../lib/lit/index.js';
import { FieldRenderer, normalizeFieldOptions } from './field-renderer.js';

// 浮层/触发框样式。multi-select-renderer 是 light DOM 且位于 flow-form shadow 内——
// document 级 CSS 穿不透 shadow boundary，各实例 connectedCallback 把 <style> 注入自身
// getRootNode()（同 table-field 模式）。
const STYLE_TEXT = `
.multi-select-renderer{display:block}
.ms-trigger{display:flex;align-items:center;gap:4px;width:100%;height:26px;padding:0 6px 0 8px;border:1px solid var(--border,#e0e0e0);border-radius:var(--radius-sm,6px);background:var(--bg,#fff);font-size:13px;cursor:pointer;box-sizing:border-box;user-select:none}
.ms-trigger:hover{border-color:var(--primary,#4f6ef7)}
.ms-trigger:focus{outline:none;border-color:var(--primary,#4f6ef7)}
.ms-trigger.ms-readonly{background:#f3f4f6;color:#6b7280;cursor:default}
.ms-trigger.ms-readonly:hover{border-color:var(--border,#e0e0e0)}
.ms-trigger-text{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left}
.ms-trigger-text.ms-placeholder{color:var(--text-muted,#6b7280)}
.ms-trigger svg{width:14px;height:14px;flex:none;color:var(--text-muted,#6b7280)}
.ms-panel{display:none;position:fixed;background:var(--bg,#fff);border:1px solid var(--border,#e0e0e0);border-radius:var(--radius-sm,6px);box-shadow:0 6px 20px rgba(0,0,0,.13);z-index:3000;min-width:200px}
.ms-panel.ms-open{display:block}
.ms-options{max-height:240px;overflow-y:auto;padding:6px 10px}
.ms-option{display:flex;align-items:center;gap:8px;padding:4px 2px;cursor:pointer}
.ms-option input[type="checkbox"]{width:16px;height:16px;margin:0;flex:none;cursor:pointer}
.ms-option label{font-weight:normal;margin:0;cursor:pointer;font-size:13px;color:var(--text,#1f2937)}
.ms-footer{display:flex;justify-content:flex-end;gap:8px;padding:8px 10px;border-top:1px solid var(--border,#e0e0e0)}
.ms-btn{padding:4px 12px;font-size:12px;font-weight:500;border-radius:var(--radius-sm,6px);cursor:pointer;border:1px solid transparent}
.ms-btn-primary{background:var(--primary,#4f6ef7);color:#fff}
.ms-btn-primary:hover{filter:brightness(1.08)}
.ms-btn-cancel{background:var(--bg,#fff);border-color:var(--border,#e0e0e0);color:var(--text,#1f2937)}
.ms-btn-cancel:hover{background:var(--secondary-light,#f1f5f9)}
`;

// Heroicons outline 风格 ▾ 三角（同 table-field ICO.chevronDown）
const CHEVRON_DOWN = html`<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>`;

// 全局单例：同时只开一个浮层；开新的把已开的按取消收起
let openInstance = null;

/**
 * 值标准化为字符串数组（value 可能来自后端回显 JSON 串/数组/逗号串）
 */
function normalizeValue(value) {
  if (Array.isArray(value)) {
    return value.map(v => String(v));
  }
  if (value === null || value === undefined) {
    return [];
  }
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) {
        return parsed.map(v => String(v));
      }
    } catch {
      // 不是 JSON，按逗号分割
      return value.split(',').map(v => v.trim()).filter(v => v);
    }
  }
  return [String(value)];
}

function escapeHtml(text) {
  if (text == null) return '';
  const div = document.createElement('div');
  div.textContent = String(text);
  return div.innerHTML;
}

/**
 * 状态化自定义元素。light DOM（createRenderRoot 返回 this）：
 * 真 checkbox 必须落进 flow-form 的 <form> 才能被 FormData 收集（shadow DOM 收不到）。
 */
export class MultiSelectRendererElement extends LitElement {
  static properties = {
    field: { type: Object },
    value: { type: Object },
    error: { type: Object },
    _selected: { state: true },   // 已提交的选中值（触发框文案/勾选态的渲染源）
    _open: { state: true },       // 浮层开合；勾选草稿只存在于 checkbox DOM，不进 state
  };

  createRenderRoot() { return this; }   // light DOM：进 flow-form <form>

  constructor() {
    super();
    this._selected = [];
    this._open = false;
    this._snapshot = null;   // 打开浮层瞬间的选中快照，取消时恢复
    this._lastFieldKey = null;
    // 文档级监听（浮层打开期间挂上，收起移除）；实例箭头函数保证解绑同一引用
    this._onDocMouseDown = ev => {
      // composedPath 含本元素（含 shadow 穿透）= 点在触发框/浮层内，放行交给自身处理
      if (ev.composedPath().includes(this)) return;
      this._cancel();
    };
    this._onDocKeydown = ev => {
      if (ev.key === 'Escape') this._cancel();
    };
    // 触发框 fixed 定位不随内容滚动 → 触发框视口位置因滚动而移动（浮层错位）才按取消收起；
    // 无关容器滚动（后台日志面板自动滚动等）不移动触发框，不得打断正在进行的勾选草稿
    this._onViewportScroll = ev => {
      if (!this._open) return;
      const t = ev.target;
      if (t && t.nodeType === 1 && this.contains(t)) return;   // 浮层内部滚动：放行
      const trigger = this.querySelector('.ms-trigger');
      const base = this._triggerRect;
      if (trigger && base) {
        const r = trigger.getBoundingClientRect();
        if (r.left === base.left && r.top === base.top) return; // 触发框未移动：无关滚动，不打断
      }
      this._cancel();
    };
    this._onViewportResize = () => this._cancel();
  }

  connectedCallback() {
    super.connectedCallback();
    // 注入样式到所在 root（同 table-field；每 root 一次，id 去重）
    const root = this.getRootNode();
    if (root && root.getElementById && !root.getElementById('ecat-multi-select-styles')) {
      const s = document.createElement('style');
      s.id = 'ecat-multi-select-styles';
      s.textContent = STYLE_TEXT;
      (root.head || root).appendChild(s);
    }
  }

  disconnectedCallback() {
    // 元素被移除（表单重渲染/翻页）时浮层一并收掉，避免悬挂 fixed 浮层与文档监听
    if (openInstance === this) this._close();
    super.disconnectedCallback();
  }

  willUpdate(changed) {
    if (changed.has('field') || changed.has('value')) {
      const fieldKey = this._fieldKey();
      // 字段 key 变化 = 元素被 flow-form positional 复用到别的字段，重置开合态防串状态
      if (this._lastFieldKey !== null && this._lastFieldKey !== fieldKey && openInstance === this) {
        this._close();
      }
      this._lastFieldKey = fieldKey;
      this._selected = normalizeValue(this.value ?? (this.field && this.field.defaultValue) ?? []);
    }
  }

  _fieldKey() { return (this.field && (this.field.key || this.field.name)) || ''; }
  _readOnly() { return !!(this.field && (this.field.readOnly || this.field.readonly)); }

  /** 选项标准化为 [{value:String,label:String}]（支持字符串数组/对象数组；
   *  兼容 Java 端 MultiSelectConfigItem 序列化：validValues + optionLabels，无 options 字段） */
  _options() {
    const raw = normalizeFieldOptions(this.field);
    if (!Array.isArray(raw)) {
      console.warn('[MultiSelectFieldRenderer] options is not an array:', raw);
      return [];
    }
    return raw.map(opt => {
      const value = typeof opt === 'object' ? opt.value : opt;
      const label = typeof opt === 'object' ? (opt.label || opt.value) : opt;
      return { value: String(value), label: String(label) };
    });
  }

  /** 从浮层 checkbox DOM 读当前勾选值（草稿真相源） */
  _checkedValues() {
    return Array.from(this.querySelectorAll('.ms-panel input[type="checkbox"]:checked')).map(i => i.value);
  }

  _onTriggerClick() {
    if (this._readOnly()) return;
    if (this._open) {
      this._cancel();
    } else {
      this._openPanel();
    }
  }

  _onTriggerKeydown(ev) {
    if (this._readOnly()) return;
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();   // 空格防页面滚动
      if (this._open) {
        this._cancel();
      } else {
        this._openPanel();
      }
    }
  }

  async _openPanel() {
    if (openInstance && openInstance !== this) openInstance._cancel();   // 全局唯一浮层
    openInstance = this;
    this._snapshot = this._checkedValues();
    this._open = true;
    document.addEventListener('mousedown', this._onDocMouseDown);
    document.addEventListener('keydown', this._onDocKeydown);
    window.addEventListener('scroll', this._onViewportScroll, true);
    window.addEventListener('resize', this._onViewportResize);
    await this.updateComplete;   // 浮层 display:block 渲染后再定位（否则量不到尺寸）
    this._positionPanel();
    // 触发框视口位置基线：滚动取消只认「触发框真的移动了」（无关容器滚动不打断勾选草稿）
    const trigger = this.querySelector('.ms-trigger');
    this._triggerRect = trigger ? trigger.getBoundingClientRect() : null;
  }

  /** 视口定位：优先落在触发框下方；下方视口放不下且上方更宽裕时翻到上方；左右夹在视口内。 */
  _positionPanel() {
    const trigger = this.querySelector('.ms-trigger');
    const panel = this.querySelector('.ms-panel');
    if (!trigger || !panel) return;
    const r = trigger.getBoundingClientRect();
    const pw = panel.offsetWidth;
    const ph = panel.offsetHeight;
    const vh = window.innerHeight;
    const vw = window.innerWidth;
    let left = r.left;
    if (left + pw > vw - 8) left = Math.max(8, vw - 8 - pw);
    let top;
    if (r.bottom + 4 + ph <= vh - 8 || r.bottom + 4 <= vh / 2) {
      top = r.bottom + 4;   // 下方放得下，或触发框在上半屏（下方仍是较优去向）
    } else {
      top = Math.max(8, r.top - 4 - ph);   // 翻到上方
    }
    panel.style.left = `${left}px`;
    panel.style.top = `${top}px`;
    panel.style.minWidth = `${Math.max(r.width, 200)}px`;
  }

  _save() {
    // 快照替换：勾选草稿转正为已提交选中 → 触发框文案更新；
    // 触发 bubbles change 让 table-field _onCellChange 按 name 聚合本 cell 全部 checked
    this._selected = this._checkedValues();
    this._close();
    this.dispatchEvent(new CustomEvent('change', { bubbles: true, composed: true }));
  }

  _cancel() {
    if (!this._open) return;
    // 恢复打开时快照（只改 DOM 勾选态，不触发 change）
    this.querySelectorAll('.ms-panel input[type="checkbox"]').forEach(i => {
      i.checked = this._snapshot.includes(i.value);
    });
    this._close();
  }

  _close() {
    this._open = false;
    this._snapshot = null;
    this._triggerRect = null;
    if (openInstance === this) openInstance = null;
    document.removeEventListener('mousedown', this._onDocMouseDown);
    document.removeEventListener('keydown', this._onDocKeydown);
    window.removeEventListener('scroll', this._onViewportScroll, true);
    window.removeEventListener('resize', this._onViewportResize);
  }

  render() {
    const fieldKey = this._fieldKey();
    const options = this._options();
    const readOnly = this._readOnly();
    const labelByValue = new Map(options.map(o => [o.value, o.label]));
    // 收起态文案 = 选中项 label 按「/」连接；label 缺失（值已不在 options）回退显原值
    const text = this._selected.map(v => labelByValue.get(v) || v).join('/');
    return html`
      <div class="form-group">
        <label for="${fieldKey}">${(this.field && this.field.displayName) || fieldKey}${this.field && this.field.required ? html`<span class="required">*</span>` : ''}</label>
        <div
          class="ms-trigger${readOnly ? ' ms-readonly' : ''}"
          id="${fieldKey}"
          role="combobox"
          aria-haspopup="true"
          aria-expanded="${this._open}"
          title="${text}"
          tabindex="${readOnly ? -1 : 0}"
          @click=${this._onTriggerClick}
          @keydown=${this._onTriggerKeydown}
        >
          <span class="ms-trigger-text${text ? '' : ' ms-placeholder'}">${text || '未选择'}</span>
          ${CHEVRON_DOWN}
        </div>
        <!-- 浮层内勾选是草稿：stopPropagation 拦下 checkbox 原生 change 冒泡，否则 table-field
             _onCellChange 会立即聚合草稿写 _rows（取消后回显文案仍是草稿值）。保存时由本元素
             显式 dispatch 的 change（源=本元素，不在浮层内）冒泡到 td 完成聚合。 -->
        <div class="ms-panel${this._open ? ' ms-open' : ''}" @change=${e => e.stopPropagation()}>
          ${readOnly
            // readOnly 补偿：disabled checkbox 不进 FormData，用 hidden input 携带已选值
            ? this._selected.map(v => html`<input type="hidden" name="${fieldKey}" value="${v}" />`)
            : ''}
          <div class="ms-options">
            ${options.map(opt => html`
              <div class="ms-option">
                <input
                  type="checkbox"
                  name="${fieldKey}"
                  value="${opt.value}"
                  id="${fieldKey}_${opt.value}"
                  ?checked=${this._selected.includes(opt.value)}
                  ?disabled=${readOnly}
                />
                <label for="${fieldKey}_${opt.value}">${escapeHtml(opt.label)}</label>
              </div>
            `)}
          </div>
          ${readOnly ? '' : html`
            <div class="ms-footer">
              <button type="button" class="ms-btn ms-btn-cancel" @click=${() => this._cancel()}>取消</button>
              <button type="button" class="ms-btn ms-btn-primary" @click=${() => this._save()}>保存</button>
            </div>
          `}
        </div>
        ${this.field && this.field.description && !this.error ? html`<div class="hint">${escapeHtml(this.field.description)}</div>` : ''}
        ${this.error ? html`<div class="error">${escapeHtml(this.error)}</div>` : ''}
      </div>
    `;
  }
}
customElements.define('multi-select-renderer', MultiSelectRendererElement);

/**
 * FieldRenderer 包装：render 产出 <multi-select-renderer>；getValue 按 getAll 聚合同名 checkbox。
 */
export class MultiSelectFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'multi_select';
  }

  /**
   * 渲染受限多选字段（下拉多选元素）
   * @param {Object} field - 字段 Schema（options: [{value, label}]）
   * @param {any} value - 当前值（字符串数组）
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    return html`<multi-select-renderer .field=${field} .value=${value} .error=${error}></multi-select-renderer>`;
  }

  /**
   * 从表单数据获取字段值
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {string[]} 选中的值数组（含 readOnly 时 hidden input 提交的值；全不选为空数组）
   */
  getValue(formData, field) {
    const fieldKey = this.getFieldKey(field);
    // FormData.getAll() 返回所有同名记录（每个 checked/hidden 的 checkbox 一条）
    const values = formData.getAll(fieldKey);
    return values.filter(v => v !== '');
  }

  /**
   * 获取默认值
   * @param {Object} field - 字段 Schema
   * @returns {string[]} 默认值数组
   */
  getDefaultValue(field) {
    return normalizeValue(field.defaultValue || []);
  }

  /**
   * 标准化值为字符串数组
   * @param {any} value - 任意值
   * @returns {string[]} 字符串数组
   */
  normalizeValue(value) {
    return normalizeValue(value);
  }

  /**
   * 解析选项数组
   * 支持多种格式：
   * - 字符串数组: ['option1', 'option2']
   * - 对象数组: [{value: 'v1', label: 'Label 1'}]
   * @param {Array} options - 原始选项数组
   * @returns {Array} 标准化的选项数组
   */
  parseOptions(options) {
    if (!Array.isArray(options)) {
      console.warn('[MultiSelectFieldRenderer] options is not an array:', options);
      return [];
    }
    return options;
  }
}
