/**
 * FieldRenderer Abstract Base Class
 * 字段渲染器抽象基类
 *
 * 所有字段类型渲染器必须继承此类
 * 使用 Strategy Pattern 实现不同字段类型的渲染
 */

/**
 * 选项归一化：兼容 Java 端 ConfigItem 序列化。
 *
 * <p>EnumConfigItem/MultiSelectConfigItem 序列化产物是 validValues（值数组）+
 * optionLabels（value→label 映射），没有 options 字段；本函数在 options 缺失/为空时
 * 由二者构造 [{value, label}]（无 label 映射时 label=值）。已有 options 的 schema 原样返回。
 *
 * @param {Object} field - 字段 Schema
 * @returns {Array} 归一化后的选项数组（可能为空数组）
 */
export function normalizeFieldOptions(field) {
  if (!field) return [];
  if (Array.isArray(field.options)) return field.options;
  const labels = (field.optionLabels && typeof field.optionLabels === 'object') ? field.optionLabels : null;
  const values = Array.isArray(field.validValues) && field.validValues.length
    ? field.validValues
    : (labels ? Object.keys(labels) : []);
  if (!values.length) return [];
  return values.map(v => ({ value: String(v), label: (labels && labels[v]) || String(v) }));
}

export class FieldRenderer {
  /**
   * 获取此渲染器支持的字段类型
   * 子类必须实现此方法
   * @returns {string} fieldType - 字段类型标识
   */
  static get fieldType() {
    throw new Error('static fieldType must be implemented by subclass');
  }

  /**
   * 渲染字段
   * 子类必须实现此方法
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    throw new Error('render() must be implemented by subclass');
  }

  /**
   * 从表单数据获取字段值
   * 子类可覆盖此方法以实现自定义值提取逻辑
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {any} 字段值
   */
  getValue(formData, field) {
    const fieldKey = field.key || field.name;
    const rawValue = formData.get(fieldKey);
    return rawValue;
  }

  /**
   * 获取默认值
   * @param {Object} field - 字段 Schema
   * @returns {any} 默认值
   */
  getDefaultValue(field) {
    return field.defaultValue;
  }

  /**
   * 获取字段的唯一标识
   * @param {Object} field - 字段 Schema
   * @returns {string} 字段标识
   */
  getFieldKey(field) {
    return field.key || field.name;
  }

  /**
   * 生成标签 HTML
   * @param {Object} field - 字段 Schema
   * @param {import('lit').TemplateResult} html - Lit html 函数
   * @returns {import('lit').TemplateResult} 标签模板
   */
  renderLabel(field, html) {
    const fieldKey = this.getFieldKey(field);
    return html`
      <label for="${fieldKey}">
        ${field.displayName || fieldKey}
        ${field.required ? html`<span class="required">*</span>` : ''}
      </label>
    `;
  }

  /**
   * 生成错误信息 HTML
   * @param {string} error - 错误信息
   * @param {import('lit').TemplateResult} html - Lit html 函数
   * @returns {import('lit').TemplateResult|null} 错误信息模板
   */
  renderError(error, html) {
    if (!error) return null;
    return html`<div class="error">${this.escapeHtml(error)}</div>`;
  }

  /**
   * HTML 转义防止 XSS
   * @param {string} text - 原始文本
   * @returns {string} 转义后的文本
   */
  escapeHtml(text) {
    if (text == null) return '';
    const div = document.createElement('div');
    div.textContent = String(text);
    return div.innerHTML;
  }
}
