/**
 * Config Flow API 工厂（lib 层，base/entryBase 参数化）。
 *
 * <p>默认参数 = SPA 现有硬编码路径（{@code /core-api/config-flows}、{@code /core-api/config-flow/entries}），
 * 保证 SPA 经 re-export 零改动。外部（Ruoyi 等）可传不同 base/entryBase 指向自己的后端代理。
 *
 * <p>与 SPA {@code core/api/config-flow-api.js} 的 configFlowApi 对象方法集一一对应（复制非引用）。
 *
 * @module lib/config-flow/flow-api
 */

/**
 * 创建 config flow API 客户端。
 * @param {Object} opts
 * @param {string} [opts.base='/core-api/config-flows'] flow 操作基础路径
 * @param {string} [opts.entryBase='/core-api/config-flow/entries'] entry 操作基础路径
 * @returns {Object} configFlowApi 实例
 */
export function createConfigFlowApi({ base = '/core-api/config-flows', entryBase = '/core-api/config-flow/entries' } = {}) {
  const json = (resp) => resp.json();
  const post = (url, body) => fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  }).then(json);

  return {
    // ==================== Flow 操作 ====================
    getProviders() {
      return fetch(`${base}/providers`).then(json);
    },
    startFlow(providerCoordinate) {
      return post(`${base}/start`, { providerCoordinate });
    },
    getStatus(flowId) {
      return fetch(`${base}/${encodeURIComponent(flowId)}`).then(json);
    },
    submitStep(flowId, stepId, userInput) {
      return post(`${base}/step`, { flowId, stepId, userInput });
    },
    goPrevious(flowId) {
      return post(`${base}/previous`, { flowId });
    },
    cancelFlow(flowId) {
      return fetch(`${base}/${encodeURIComponent(flowId)}`, { method: 'DELETE' }).then(json);
    },

    // ==================== ConfigEntry 操作 ====================
    listEntries(coordinate = '') {
      const url = coordinate ? `${entryBase}?coordinate=${encodeURIComponent(coordinate)}` : entryBase;
      return fetch(url).then(json);
    },
    getEntry(entryId) {
      return fetch(`${entryBase}/${encodeURIComponent(entryId)}`).then(json);
    },
    deleteEntry(entryId) {
      return fetch(`${entryBase}/${encodeURIComponent(entryId)}`, { method: 'DELETE' }).then(json);
    },
    enableEntry(entryId) {
      return post(`${entryBase}/enable`, { entryId });
    },
    disableEntry(entryId) {
      return post(`${entryBase}/disable`, { entryId });
    },
    reconfigureEntry(entryId) {
      return post(`${entryBase}/reconfigure`, { entryId });
    },

    // ==================== Discovery（自发现提示/忽略，IMPORT_FLOW/ZEROCONF/MQTT 三源统一）====================
    listDiscoveries() {
      return fetch(`${base}/discoveries`).then(json);
    },
    ignoreDiscovery(coordinate, uniqueId, title = '') {
      return post(`${entryBase}/ignore`, { coordinate, uniqueId, title });
    },
    unignoreDiscovery(uniqueId) {
      return post(`${entryBase}/unignore`, { uniqueId });
    },
    listIgnored() {
      return fetch(`${entryBase}/ignored`).then(json);
    }
  };
}

// 默认实例（= SPA 现有路径），供 SPA re-export 零改动；外部按需 createConfigFlowApi({...})
export const configFlowApi = createConfigFlowApi();
